'use client';
import { useMemo, useState } from 'react';
import { Lumio } from '@/components/AppShell';
type Lesson = { id: string; title: string; position: number; pass_score: number };
type Question = { id: string; lesson_id: string; prompt: string; explanation: string; option_a: string; option_b: string; option_c: string; option_d: string; correct_option: 'A'|'B'|'C'|'D' };
export function LearnClient({ lessons, questions, courseName = 'Kurs' }: { lessons: Lesson[]; questions: Question[]; courseName?: string }){ const [lessonIndex,setLessonIndex]=useState(0); const [questionIndex,setQuestionIndex]=useState(0); const [selected,setSelected]=useState<string|null>(null); const [correctCount,setCorrectCount]=useState(0); const [message,setMessage]=useState(''); const lesson = lessons[lessonIndex]; const lessonQuestions = useMemo(() => questions.filter((q) => q.lesson_id === lesson?.id), [questions, lesson]); const question = lessonQuestions[questionIndex]; const options = question ? [{key:'A',value:question.option_a},{key:'B',value:question.option_b},{key:'C',value:question.option_c},{key:'D',value:question.option_d}] : []; function choose(key:string){ if(selected) return; setSelected(key); if(key===question.correct_option) setCorrectCount((v)=>v+1); }
async function next(){ if(questionIndex < lessonQuestions.length - 1){ setQuestionIndex((v)=>v+1); setSelected(null); return; } const totalCorrect = selected === question.correct_option ? correctCount + 1 : correctCount; const score = Math.round((totalCorrect / lessonQuestions.length) * 100); const passed = score >= lesson.pass_score; const xpAwarded = totalCorrect * 20 + (passed ? 50 : 0); const response = await fetch('/api/lesson-complete', { method:'POST', headers:{ 'Content-Type':'application/json' }, body: JSON.stringify({ lessonId: lesson.id, score, correctAnswers: totalCorrect, totalQuestions: lessonQuestions.length, passed, lastQuestionIndex: lessonQuestions.length, xpAwarded }) }); const result = await response.json(); setMessage(result.message ? `${result.message} ${passed ? `Bestanden mit ${score}%` : `Nicht bestanden mit ${score}%`}` : ''); setQuestionIndex(0); setSelected(null); setCorrectCount(0); }
return <div className="grid grid-2"><div className="card stack"><div className="hero"><div><h2>Lektionen</h2><p className="muted">{courseName} · linearer Pfad wie im Pflichtenheft.</p></div><Lumio /></div>{lessons.map((item,index)=><button className="btn" key={item.id} onClick={()=>{ setLessonIndex(index); setQuestionIndex(0); setSelected(null); setCorrectCount(0); setMessage(''); }}>{item.position}. {item.title}</button>)}</div><div className="card stack">{question ? <><div className="hero"><div><div className="pill">Frage {questionIndex + 1} / {lessonQuestions.length}</div><h2>{question.prompt}</h2><p className="muted">Lumio gibt direktes Feedback mit Erklärung.</p></div><Lumio /></div>{options.map((option)=>{ const cls = selected ? option.key === question.correct_option ? 'option correct' : option.key === selected ? 'option wrong' : 'option' : 'option'; return <button key={option.key} className={cls} onClick={()=>choose(option.key)}>{option.value}</button>; })}{selected ? <div className="card">{selected === question.correct_option ? 'RICHTIG! +20 XP — ' : 'Leider Nein! -10 XP — '}{question.explanation}</div> : null}<button className="btn btn-primary" onClick={next} disabled={!selected}>{questionIndex < lessonQuestions.length - 1 ? 'Nächste Frage' : 'Lektion abschliessen'}</button>{message ? <div>{message}</div> : null}</> : <p className="muted">Keine Fragen vorhanden.</p>}</div></div>; }